//! 🧪️ Actual encoded source fixtures, shared owners, private publication and every cancellation phase.
use super::*;
use crate::schema::scene_preparation::{DocumentSceneJob,DocumentSceneLimits};
use crate::schema::scene_preparation::tests::{close_plan,close_owned,close_raster};
use std::collections::BTreeSet;
use serde_json::Value;
fn rows()->Vec<Value>{serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()}
fn limits(v:&Value)->DocumentTraceLimits{DocumentTraceLimits{max_pixels:v["maxPixels"].as_u64().unwrap()as usize,max_admitted_pixels:v["maxAdmittedPixels"].as_u64().unwrap()as usize,max_source_bytes:v["maxSourceBytes"].as_u64().unwrap()as usize,max_edges:v["maxEdges"].as_u64().unwrap()as usize,max_segments:v["maxSegments"].as_u64().unwrap()as usize,max_retained_segments:v["maxRetainedSegments"].as_u64().unwrap()as usize,max_work:v["maxWork"].as_u64().unwrap()}}
fn input(row:&Value)->DocumentTraceInput{let document:crate::DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let v=&row["preparation"];let mut job=DocumentSceneJob::new(&document,DocumentSceneLimits{max_nodes:v["maxNodes"].as_u64().unwrap()as usize,max_depth:v["maxDepth"].as_u64().unwrap()as usize,max_segments:v["maxSegments"].as_u64().unwrap()as usize,max_references:v["maxReferences"].as_u64().unwrap()as usize,max_source_bytes:v["maxSourceBytes"].as_u64().unwrap()as usize}).unwrap();while !job.advance(4096).unwrap().done{}DocumentTraceInput{plan:job.result().unwrap(),limits:limits(&row["limits"])}}
fn finish(input:DocumentTraceInput,grant:usize)->(DocumentScenePlan,DocumentTraceProgress){let mut job=DocumentTraceJob::new(input).unwrap();assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));let mut work=0;loop{let p=job.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{let(mut close,input,output)=job.into_retirement();crate::draw_scene_physical_close!(close,1);close_plan(input);return(output.unwrap(),p);}assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));}}
fn rings(segments:&[DrawingSegment])->Vec<Vec<[f64;2]>>{let mut rings=Vec::new();for s in segments{match s{DrawingSegment::Move{to}=>rings.push(vec![*to]),DrawingSegment::Line{to}=>rings.last_mut().unwrap().push(*to),DrawingSegment::Close=>{},_=>panic!("Unexpected trace curve")}}rings}
fn area(segments:&[DrawingSegment])->f64{rings(segments).into_iter().map(|r|{let mut sum=0.0;for i in 0..r.len(){let(a,b)=(r[i],r[(i+1)%r.len()]);sum+=(a[0]*b[1]-b[0]*a[1])/2.0;}sum}).sum::<f64>().abs()}
fn foreground(segments:&[DrawingSegment],width:usize,height:usize)->Vec<u8>{let rings=rings(segments);(0..width*height).map(|at|{let(x,y)=((at%width)as f64+0.5,(at/width)as f64+0.5);let mut winding=0;for r in &rings{for i in 0..r.len(){let(a,b)=(r[i],r[(i+1)%r.len()]);let cross=(b[0]-a[0])*(y-a[1])-(b[1]-a[1])*(x-a[0]);if a[1]<=y&&b[1]>y&&cross>0.0{winding+=1;}else if a[1]>y&&b[1]<=y&&cross<0.0{winding-=1;}}}u8::from(winding!=0)}).collect()}
#[test]
fn painted_scenes_actual_image_trace_documents_keep_native_coordinates_and_shared_sources(){
 for row in rows(){let value=input(&row);let mut previous=None;for grant in [1,7,4096]{let(plan,p)=finish(value.clone(),grant);assert_eq!(p.admitted_images,row["expected"]["admittedImages"].as_u64().unwrap()as usize);assert_eq!(p.pixels,row["expected"]["pixels"].as_u64().unwrap()as usize);for expected in row["expected"]["traces"].as_array().unwrap(){let id=expected["id"].as_str().unwrap();let node=plan.nodes.iter().find(|n|n.id==id).unwrap();let original=value.plan.nodes.iter().find(|n|n.id==id).unwrap();assert_eq!(node.transform,original.transform);assert_eq!(node.visible,original.visible);assert_eq!(node.opacity,original.opacity);assert_eq!(node.blend_mode,original.blend_mode);assert_eq!(format!("{:?}",node.groups),format!("{:?}",original.groups));
   let DocumentSceneContent::Path{segments,fill_rule,fill,stroke}=&node.content else{panic!("Unresolved trace")};let DocumentSceneContent::Trace{fill_rule:before_rule,fill:before_fill,stroke:before_stroke,..}=&original.content else{panic!("Expected trace input")};assert_eq!(fill_rule,before_rule);assert_eq!(format!("{fill:?}"),format!("{before_fill:?}"));assert_eq!(format!("{stroke:?}"),format!("{before_stroke:?}"));
   assert_eq!(area(segments),expected["area"].as_f64().unwrap());assert_eq!(rings(segments).len(),expected["contours"].as_u64().unwrap()as usize);assert_eq!(foreground(segments,row["source"]["width"].as_u64().unwrap()as usize,row["source"]["height"].as_u64().unwrap()as usize),expected["foreground"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>());
  }let actual=format!("{plan:?}");if let Some(before)=previous{assert_eq!(actual,before);}previous=Some(actual);println!("[DEBUG] Native actual trace {} grant={grant} decodes={} pixels={} work={}",row["name"],p.admitted_images,p.pixels,p.work);}}
}
#[test]
fn painted_scenes_trace_source_params_and_resource_failures_are_private(){
 let source=input(&rows()[0]);for kind in 0..4{let mut v=source.clone();match kind{0=>v.limits.max_work=0,1=>v.limits.max_pixels=0,2=>v.limits.max_admitted_pixels=0,_=>v.limits.max_retained_segments=0}assert!(DocumentTraceJob::new(v).is_err());}
 for kind in 0..13{let mut v=source.clone();match kind{0=>{let DocumentSceneContent::Trace{source,..}=&mut v.plan.nodes[0].content else{panic!()};*source="absent".into()},1=>v.plan.assets.push(v.plan.assets[0].clone()),2=>v.plan.assets[0].image=Arc::new(RasterImage{width:0,height:1,pixels:vec![]}),3=>v.plan.assets[0].image=Arc::new(RasterImage{width:1,height:1,pixels:vec![]}),4=>{let DocumentSceneContent::Trace{threshold,..}=&mut v.plan.nodes[0].content else{panic!()};*threshold=f64::NAN},5=>{let DocumentSceneContent::Trace{simplify_epsilon,..}=&mut v.plan.nodes[0].content else{panic!()};*simplify_epsilon=8193.0},6=>v.limits.max_pixels=8,7=>v.limits.max_admitted_pixels=8,8=>v.limits.max_source_bytes=1,9=>v.limits.max_edges=1,10=>v.limits.max_segments=1,11=>v.limits.max_retained_segments=1,_=>v.limits.max_work=1}
  let mut job=DocumentTraceJob::new(v).unwrap();let error=job.advance(10000000).unwrap_err();assert_eq!(job.result().unwrap_err(),error);assert_eq!(job.advance(1).unwrap_err(),error);close_owned(job);}
 assert!(DocumentTraceJob::new(source).unwrap().advance(0).is_err());
}
#[test]
fn painted_scenes_trace_aggregate_resources_charge_shared_sources_once(){
 let source=input(&rows()[4]);let mut exact=source.clone();exact.limits.max_source_bytes=source.plan.assets[0].image.pixels.len();exact.limits.max_admitted_pixels=9;assert_eq!(finish(exact,7).0.nodes.len(),2);
 for pixels in [false,true]{let mut v=source.clone();let mut a=v.plan.assets[0].clone();a.id="second".into();v.plan.assets.push(a);let DocumentSceneContent::Trace{source,..}=&mut v.plan.nodes[1].content else{panic!()};*source="second".into();if pixels{v.limits.max_admitted_pixels=17}else{v.limits.max_source_bytes=v.plan.assets[0].image.pixels.len()*2-1}let mut job=DocumentTraceJob::new(v).unwrap();assert!(job.advance(10000000).is_err());assert!(job.result().is_err());close_owned(job);}
}
#[test]
fn painted_scenes_trace_cancellation_and_exact_budgets_keep_owned_output(){
 let source=input(&rows()[0]);let mut probe=DocumentTraceJob::new(source.clone()).unwrap();let mut seen=BTreeSet::new();let last;loop{let p=probe.advance(1).unwrap();if seen.insert(p.phase){let mut job=DocumentTraceJob::new(source.clone()).unwrap();job.advance(p.work as usize).unwrap();job.cancel();assert!(matches!(job.result(),Err(DocumentSceneError::Cancelled)));assert!(matches!(job.advance(1),Err(DocumentSceneError::Cancelled)));close_owned(job);}if p.done{last=p;break;}}
 assert_eq!(seen,BTreeSet::from(["assets","indexing","nodes","luma","tracing","publishing","complete"]));let published=probe.result().unwrap().clone();probe.cancel();assert_eq!(published.nodes.len(),1);close_owned(probe);
 let mut exact=source;exact.limits.max_work=last.work;exact.limits.max_admitted_pixels=last.pixels;exact.limits.max_retained_segments=last.segments;exact.limits.max_source_bytes=last.source_bytes;assert_eq!(format!("{:?}",finish(exact,7).0),format!("{published:?}"));
}
fn preparation(v:&Value)->DocumentSceneLimits{DocumentSceneLimits{max_nodes:v["maxNodes"].as_u64().unwrap()as usize,max_depth:v["maxDepth"].as_u64().unwrap()as usize,max_segments:v["maxSegments"].as_u64().unwrap()as usize,max_references:v["maxReferences"].as_u64().unwrap()as usize,max_source_bytes:v["maxSourceBytes"].as_u64().unwrap()as usize}}
fn viewport(v:&Value)->crate::schema::scene_preparation::DocumentSceneViewport{crate::schema::scene_preparation::DocumentSceneViewport{width:v["width"].as_u64().unwrap()as u32,height:v["height"].as_u64().unwrap()as u32,origin:[v["origin"][0].as_f64().unwrap(),v["origin"][1].as_f64().unwrap()],tolerance:v["tolerance"].as_f64().unwrap(),max_pixels:v["maxPixels"].as_u64().unwrap()as usize,max_source_bytes:v["maxSourceBytes"].as_u64().unwrap()as usize}}
fn configuration(row:&Value)->crate::schema::scene_preparation::DocumentAlgorithmLimits{let v=&row["booleans"];crate::schema::scene_preparation::DocumentAlgorithmLimits{max_work:10000000,trace:limits(&row["limits"]),booleans:crate::schema::scene_booleans::DocumentBooleanLimits{tolerance:v["tolerance"].as_f64().unwrap(),epsilon:v["epsilon"].as_f64().unwrap(),max_depth:v["maxDepth"].as_u64().unwrap()as usize,max_references:v["maxReferences"].as_u64().unwrap()as usize,max_edges:v["maxEdges"].as_u64().unwrap()as usize,max_parameters:v["maxParameters"].as_u64().unwrap()as usize,max_atomic_edges:v["maxAtomicEdges"].as_u64().unwrap()as usize,max_segments:v["maxSegments"].as_u64().unwrap()as usize,max_retained_segments:v["maxRetainedSegments"].as_u64().unwrap()as usize,max_work:v["maxWork"].as_u64().unwrap()}}}
#[test]
fn painted_scenes_actual_trace_raster_documents_forward_real_source_and_contour_progress(){
 use crate::schema::scene_preparation::DocumentRasterJob;
 for row in rows(){let doc:crate::DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let mut previous=None;for grant in [1,7,4096]{let mut job=DocumentRasterJob::new(&doc,preparation(&row["preparation"]),viewport(&row["viewport"]),configuration(&row)).unwrap();let(mut work,mut decode,mut trace)=(0,false,false);loop{let p=job.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.tracing.is_some_and(|p|p.phase=="luma"){decode=true;assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));}if p.tracing.and_then(|p|p.trace).is_some_and(|p|!p.done){trace=true;assert!(matches!(job.result(),Err(DocumentSceneError::Incomplete)));}if p.done{break;}}if grant==1{assert!(decode&&trace);}let image=job.result().unwrap();if let Some(before)=previous{assert_eq!(image.pixels,before);}previous=Some(image.pixels);println!("[DEBUG] Native actual trace document pixels {} grant={grant} source/contour work={work}",row["name"]);close_raster(job);}}
}
#[test]
fn painted_scenes_whole_trace_document_work_cap_cancels_every_stage_privately(){
 use crate::schema::scene_preparation::DocumentRasterJob;
 let row=&rows()[0];let doc:crate::DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let base=configuration(row);let mut job=DocumentRasterJob::new(&doc,preparation(&row["preparation"]),viewport(&row["viewport"]),base).unwrap();let mut seen=BTreeSet::new();let work;loop{let p=job.advance(1).unwrap();if seen.insert(p.phase){let mut cancelled=DocumentRasterJob::new(&doc,preparation(&row["preparation"]),viewport(&row["viewport"]),base).unwrap();cancelled.advance(p.work as usize).unwrap();cancelled.cancel();assert!(matches!(cancelled.result(),Err(DocumentSceneError::Cancelled)));assert!(matches!(cancelled.advance(1),Err(DocumentSceneError::Cancelled)));close_raster(cancelled);}if p.done{work=p.work;break;}}assert_eq!(seen,BTreeSet::from(["preparing","tracing","algorithms","resolving","raster","complete"]));let expected=job.result().unwrap().pixels;close_raster(job);
 let mut config=base;config.max_work=work;let mut exact=DocumentRasterJob::new(&doc,preparation(&row["preparation"]),viewport(&row["viewport"]),config).unwrap();while !exact.advance(7).unwrap().done{}assert_eq!(exact.result().unwrap().pixels,expected);close_raster(exact);for cap in [1,work-1]{config.max_work=cap;let mut refused=DocumentRasterJob::new(&doc,preparation(&row["preparation"]),viewport(&row["viewport"]),config).unwrap();let error=refused.advance(10000000).unwrap_err();assert!(error.to_string().contains("work limit"));assert_eq!(refused.result().unwrap_err(),error);assert_eq!(refused.advance(1).unwrap_err(),error);close_raster(refused);}config.max_work=0;assert!(DocumentRasterJob::new(&doc,preparation(&row["preparation"]),viewport(&row["viewport"]),config).is_err());
}

#[test]
fn document_trace_retirement_composes_actual_kernel_and_private_scene_owners(){
 use crate::schema::scene_retirement::ScenePlanCloseJob;
 let fixtures:Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧹️retirement/🔣️.json")).unwrap();
 for sample in fixtures["cases"].as_array().unwrap(){for grant in [1,7,4096]{let row=rows().into_iter().find(|r|r["name"]==*sample.get("source").unwrap_or(&fixtures["source"])).unwrap();let mut source=input(&row);let m=&fixtures["metadata"];for n in &mut source.plan.nodes{n.groups.push(crate::schema::DrawingSceneGroup{id:m["group"]["id"].as_str().unwrap().into(),opacity:m["group"]["opacity"].as_f64().unwrap(),blend_mode:m["group"]["blendMode"].as_str().unwrap().into()});}let DocumentSceneContent::Trace{fill,stroke,..}=&mut source.plan.nodes.iter_mut().find(|n|matches!(n.content,DocumentSceneContent::Trace{..})).unwrap().content else{panic!()};*fill=Some(serde_json::from_value(m["fill"].clone()).unwrap());*stroke=Some(serde_json::from_value(m["stroke"].clone()).unwrap());
  if let Some(n)=sample["maxWork"].as_u64(){source.limits.max_work=n;}if let Some(n)=sample["maxRetainedSegments"].as_u64(){source.limits.max_retained_segments=n as usize;}let source_ptr=source.plan.nodes.as_ptr();let shared_source=source.plan.assets[0].image.clone();let mut job=DocumentTraceJob::new(source).unwrap();let phase=sample["phase"].as_str().unwrap();
  if phase=="failure"{assert!(job.advance(100000).is_err());if sample["maxWork"].is_number(){assert!(!job.catalog.values.is_empty());}}else if phase!="fresh"{if phase!="cancelled"{let mut reached=false;for _ in 0..100000{if job.advance(1).unwrap().phase==phase&&(sample.get("checkpoint").is_none()||job.closing_tracer.is_some()){reached=true;break;}}assert!(reached);}for _ in 0..sample["offset"].as_u64().unwrap(){job.advance(1).unwrap();}}
  if phase=="cancelled"{job.cancel();}let published=if phase=="complete"{Some(job.result().unwrap().nodes.as_ptr())}else{None};let(mut close,input,output)=job.into_retirement();if let Some(ptr)=published{assert!(input.nodes.is_empty());assert_eq!(output.as_ref().unwrap().nodes.as_ptr(),ptr);close_plan(output.unwrap());}else{assert!(output.is_none());if phase!="cancelled"{assert_eq!(input.nodes.as_ptr(),source_ptr);}}
  assert!(close.advance(0).is_err());let work=crate::draw_scene_physical_close!(close,grant);assert!(close.terminal_is_empty());assert_eq!(close.close_step(semio_framework_value::retained_clone::RetainedCloneGrant::default()).unwrap().progress(),Default::default());close_plan(input);assert_eq!(Arc::strong_count(&shared_source),1);println!("[DEBUG] Native document trace {phase} composed and retired private owners in {work} work units at grant {grant}");
 }}
}
